export function formatPrice(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`
}

export function debounce<T extends unknown[]>(fn: (...args: T) => void, ms: number) {
  let t: ReturnType<typeof setTimeout>
  return (...args: T) => {
    clearTimeout(t)
    t = setTimeout(() => fn(...args), ms)
  }
}
